136	  public void updateMetrics(final BeaconState state) {
137	    final Eth1Data currentEth1Data = state.getEth1Data();
138	    // Avoid using .values() directly as it has O(n) lookup which gets expensive fast
139	    final Set<Eth1Data> knownBlocks =
140	        new HashSet<>(
141	            getVotesToConsider(state.getSlot(), state.getGenesisTime(), currentEth1Data).values());
142	    Map<Eth1Data, Eth1Vote> votes = countVotes(state);
143	
144	    currentPeriodVotesMax.set(eth1VotingPeriod.getTotalSlotsInVotingPeriod(state.getSlot()));
145	    currentPeriodVotesTotal.set(state.getEth1DataVotes().size());
146	    currentPeriodVotesUnknown.set(
147	        votes.keySet().stream().filter(votedBlock -> !knownBlocks.contains(votedBlock)).count());
148	    currentPeriodVotesCurrent.set(
149	        votes.getOrDefault(currentEth1Data, new Eth1Vote(0)).getVoteCount());
150	
151	    currentPeriodVotesBest.set(
152	        votes.values().stream()
153	            .max(Comparator.naturalOrder())
154	            .map(Eth1Vote::getVoteCount)
155	            .orElse(0));
156	  }
157	
158	  protected Map<Eth1Data, Eth1Vote> countVotes(final BeaconState state) {
159	    Map<Eth1Data, Eth1Vote> votes = new HashMap<>();
160	    int i = 0;
161	    for (Eth1Data eth1Data : state.getEth1DataVotes()) {
162	      final int currentIndex = i;
163	      votes.computeIfAbsent(eth1Data, key -> new Eth1Vote(currentIndex)).incrementVotes();
164	      i++;
165	    }
166	    return votes;
167	  }
