32	class AsyncRunLoopTest {
33	  private static final Duration RETRY_DELAY = Duration.ofSeconds(10);
34	  private final RunLoopLogic logic = mock(RunLoopLogic.class);
35	  private final StubTimeProvider timeProvider = StubTimeProvider.withTimeInMillis(100_000);
36	  private final StubAsyncRunner asyncRunner = new StubAsyncRunner(timeProvider);
37	
38	  private final AsyncRunLoop runLoop = new AsyncRunLoop(logic, asyncRunner, RETRY_DELAY);
39	
40	  @BeforeEach
41	  void setUp() {
42	    // By default init completes but advance doesn't
43	    when(logic.init()).thenReturn(SafeFuture.COMPLETE);
44	    when(logic.advance()).thenReturn(new SafeFuture<>());
45	  }
46	
47	  @Test
48	  void shouldCallInitWhenStarted() {
49	    runLoop.start();
50	
51	    verify(logic).init();
52	  }
53	
54	  @Test
55	  void shouldRetryAfterDelayIfInitFails() {
56	    final Throwable error = new RuntimeException("Computer says no");
57	    when(logic.init()).thenReturn(SafeFuture.failedFuture(error)).thenReturn(SafeFuture.COMPLETE);
58	
59	    runLoop.start();
60	
61	    verify(logic).init();
62	    verify(logic).onError(error);
63	
64	    assertThat(asyncRunner.hasDelayedActions()).isTrue();
65	    advanceTime(RETRY_DELAY);
66	    verify(logic, times(2)).init();
67	  }
68	
69	  @Test
70	  void shouldWaitThenCallAdvanceAfterInitCompletes() {
71	    final SafeFuture<Void> initResult = new SafeFuture<>();
72	    final Duration advanceDelay = Duration.ofSeconds(3);
73	    when(logic.init()).thenReturn(initResult);
74	    when(logic.getDelayUntilNextAdvance()).thenReturn(advanceDelay);
75	
76	    runLoop.start();
77	    verify(logic).init();
78	    verifyNoMoreInteractions(logic);
79	
80	    // Time advances but because init hasn't completed we are no closer to triggering advance
81	    advanceTime(advanceDelay);
82	
83	    initResult.complete(null);
84	    verify(logic).getDelayUntilNextAdvance();
85	    verifyNoMoreInteractions(logic);
86	
87	    // Delay starts after init completes and then triggers advance when due
88	    advanceTime(advanceDelay);
89	
90	    verify(logic).advance();
91	    verifyNoMoreInteractions(logic);
92	  }
93	
94	  @Test
95	  void shouldScheduleNextAdvanceWhenFirstAdvanceCompletes() {
96	    final Duration firstAdvanceDelay = Duration.ofSeconds(2);
97	    final Duration secondAdvanceDelay = Duration.ofSeconds(20);
98	    when(logic.advance()).thenReturn(SafeFuture.COMPLETE).thenReturn(new SafeFuture<>());
99	    when(logic.getDelayUntilNextAdvance()).thenReturn(firstAdvanceDelay, secondAdvanceDelay);
100	
101	    runLoop.start();
102	    verify(logic).init();
103	    verify(logic, never()).advance();
104	
105	    advanceTime(firstAdvanceDelay);
106	    verify(logic, times(1)).advance();
107	
108	    // Shouldn't use same delay for second advance so this won't wait long enough
109	    advanceTime(firstAdvanceDelay);
110	    verify(logic, times(1)).advance();
111	
112	    // Advance remaining time until second advance is due and confirm it is invoked
113	    advanceTime(secondAdvanceDelay.minus(firstAdvanceDelay));
114	    verify(logic, times(2)).advance();
115	
116	    verify(logic, atLeastOnce()).getDelayUntilNextAdvance();
117	    verifyNoMoreInteractions(logic);
118	  }
119	
120	  @Test
121	  void shouldRetryAfterDelayWhenAdvanceFails() {
122	    final Duration advanceDelay = Duration.ofSeconds(5);
123	    final Throwable error = new RuntimeException("Computer says no");
124	    when(logic.advance()).thenReturn(SafeFuture.failedFuture(error)).thenReturn(new SafeFuture<>());
125	    when(logic.getDelayUntilNextAdvance()).thenReturn(advanceDelay);
126	
127	    runLoop.start();
128	    advanceTime(advanceDelay);
129	
130	    verify(logic).advance();
131	    verify(logic).onError(error);
132	
133	    assertThat(asyncRunner.hasDelayedActions()).isTrue();
134	    advanceTime(RETRY_DELAY);
135	
136	    verify(logic, times(2)).advance();
137	  }
138	
139	  private void advanceTime(final Duration advanceDelay) {
140	    timeProvider.advanceTimeBy(advanceDelay);
141	    asyncRunner.executeDueActions();
142	  }
143	}
