16	import static com.google.common.base.Preconditions.checkState;
17	
18	import java.util.concurrent.atomic.AtomicReference;
19	import tech.pegasys.teku.infrastructure.async.SafeFuture;
20	
21	public abstract class Service implements ServiceFacade {
22	  enum State {
23	    IDLE,
24	    RUNNING,
25	    STOPPED
26	  }
27	
28	  private final AtomicReference<State> state = new AtomicReference<>(State.IDLE);
29	
30	  @Override
31	  public SafeFuture<?> start() {
32	    if (!state.compareAndSet(State.IDLE, State.RUNNING)) {
33	      return SafeFuture.failedFuture(
34	          new IllegalStateException("Attempt to start an already started service."));
35	    }
36	    return doStart();
37	  }
38	
39	  protected abstract SafeFuture<?> doStart();
40	
41	  @Override
42	  public SafeFuture<?> stop() {
43	    if (state.compareAndSet(State.RUNNING, State.STOPPED)) {
44	      return doStop();
45	    } else {
46	      // Return a successful future if there's nothing to do at this point
47	      return SafeFuture.COMPLETE;
48	    }
49	  }
50	
51	  protected abstract SafeFuture<?> doStop();
52	
53	  @Override
54	  public boolean isRunning() {
55	    return state.get() == State.RUNNING;
56	  }
57	
58	  protected void assertIsRunning(final String action) {
59	    checkState(isRunning(), "Service must be running to execute action '%s'", action);
60	  }
61	}
