263	  protected SafeFuture<?> doStart() {
264	    if (isFormerDepositMechanismDisabled()) {
265	      // The former (Eth1 based) deposit mechanism is no longer active, there is no point in setting
266	      // up and starting the Eth1 deposit polling.
267	      LOG.info(
268	          "Not starting Eth1 deposit polling: the former deposit mechanism has been disabled.");
269	      return SafeFuture.COMPLETE;
270	    }
271	    initialize();
272	    hasInitialized.set(true);
273	    return SafeFuture.allOfFailFast(
274	        SafeFuture.fromRunnable(headTracker::start),
275	        SafeFuture.fromRunnable(eth1DepositManager::start),
276	        SafeFuture.fromRunnable(eth1Providers::start));
277	  }
