279	  @Override
280	  protected SafeFuture<?> doStop() {
281	    if (!hasInitialized.get()) {
282	      // Nothing was ever started so there is nothing to stop.
283	      return SafeFuture.COMPLETE;
284	    }
285	    return SafeFuture.allOfFailFast(
286	        Stream.concat(
287	                Stream.<ExceptionThrowingRunnable>of(
288	                    headTracker::stop, eth1DepositManager::stop, eth1Providers::stop),
289	                web3js.stream().map(web3j -> web3j::shutdown))
290	            .map(SafeFuture::fromRunnable)
291	            .toArray(SafeFuture[]::new));
292	  }
